// ─── File: CrossInstanceDemo.java ───
// Runnable demo: local memory does NOT propagate; DB + Redis + events do.

import java.math.BigDecimal;
import java.util.*;
import java.util.function.Consumer;
import java.util.logging.*;

public class CrossInstanceDemo {

    private static final Logger log = Logger.getLogger("crossinstance");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SharedDatabase db = new SharedDatabase();          // one source of truth
        RedisCache redis = new RedisCache();               // one shared cache
        EventBus bus = new EventBus();                     // Kafka stand-in

        BalanceInstance app1 = new BalanceInstance("App1", db, redis, bus);
        BalanceInstance app2 = new BalanceInstance("App2", db, redis, bus);

        // Prime both local caches with the current balance.
        app1.readBalance("SAV2001");
        app2.readBalance("SAV2001");

        log.info("===== BROKEN: App1 updates LOCAL memory only =====");
        app1.updateLocalOnly("SAV2001", new BigDecimal("950000"));  // only App1's heap
        app2.readBalance("SAV2001");   // App2 still stale

        log.info("===== CORRECT: DB source of truth + event-driven invalidation =====");
        app1.updateBalance("SAV2001", new BigDecimal("900000"));    // DB + Redis + event
        app2.readBalance("SAV2001");   // App2 now fresh
    }
}

// ─── model/Account.java ───
class Account {
    final String id; BigDecimal balance; long version;
    Account(String id, BigDecimal balance, long version) { this.id = id; this.balance = balance; this.version = version; }
}

// ─── shared/SharedDatabase.java — source of truth ───
class SharedDatabase {
    private final Map<String, Account> rows = new HashMap<>();
    SharedDatabase() { rows.put("SAV2001", new Account("SAV2001", new BigDecimal("1000000"), 0)); }
    synchronized BigDecimal read(String id) { return rows.get(id).balance; }
    synchronized void write(String id, BigDecimal bal) {
        Account a = rows.get(id); a.balance = bal; a.version++;
    }
}

// ─── shared/RedisCache.java — shared distributed cache ───
class RedisCache {
    private final Map<String, BigDecimal> store = new HashMap<>();
    BigDecimal get(String key) { return store.get(key); }
    void put(String key, BigDecimal v) { store.put(key, v); }
    void evict(String key) { store.remove(key); }
}

// ─── local/LocalCache.java — PER-INSTANCE, not shared ───
class LocalCache {
    private final Map<String, BigDecimal> store = new HashMap<>();
    BigDecimal get(String key) { return store.get(key); }
    void put(String key, BigDecimal v) { store.put(key, v); }
    void evict(String key) { store.remove(key); }
}

// ─── event/BalanceChangedEvent.java ───
class BalanceChangedEvent {
    final String accountId; final String source;
    BalanceChangedEvent(String accountId, String source) { this.accountId = accountId; this.source = source; }
}

// ─── event/EventBus.java — Kafka stand-in (broadcast to all instances) ───
class EventBus {
    private final List<Consumer<BalanceChangedEvent>> subs = new ArrayList<>();
    void subscribe(Consumer<BalanceChangedEvent> s) { subs.add(s); }
    void publish(BalanceChangedEvent e) { subs.forEach(s -> s.accept(e)); }
}

// ─── instance/BalanceInstance.java — one JVM instance ───
class BalanceInstance {
    private static final Logger log = Logger.getLogger("crossinstance");
    private final String name;
    private final SharedDatabase db; private final RedisCache redis; private final EventBus bus;
    private final LocalCache local = new LocalCache();   // private to THIS instance

    BalanceInstance(String name, SharedDatabase db, RedisCache redis, EventBus bus) {
        this.name = name; this.db = db; this.redis = redis; this.bus = bus;
        // Each instance subscribes to invalidate its OWN local cache on change.
        bus.subscribe(this::onBalanceChanged);
    }

    BigDecimal readBalance(String id) {
        BigDecimal v = local.get(id);                       // 1) local cache
        if (v != null) { log.info(() -> "[" + name + "] local hit " + id + " = Rs." + v); return v; }
        v = redis.get(id);                                  // 2) shared Redis
        if (v == null) { v = db.read(id); redis.put(id, v); }  // 3) DB source of truth
        local.put(id, v);
        BigDecimal fv = v;
        log.info(() -> "[" + name + "] loaded " + id + " = Rs." + fv + " (from shared store)");
        return v;
    }

    // BUG: updates only this instance's memory — invisible to others.
    void updateLocalOnly(String id, BigDecimal bal) {
        local.put(id, bal);
        log.warning(() -> "[" + name + "] updated LOCAL cache only " + id + " = Rs." + bal + " (others won't see it)");
    }

    // CORRECT: write source of truth, refresh Redis, publish event to invalidate everyone.
    void updateBalance(String id, BigDecimal bal) {
        db.write(id, bal);          // source of truth
        redis.put(id, bal);         // refresh shared cache
        local.put(id, bal);         // this instance fresh
        bus.publish(new BalanceChangedEvent(id, name));   // tell all instances
        log.info(() -> "[" + name + "] committed DB + Redis + published BalanceChanged " + id + " = Rs." + bal);
    }

    private void onBalanceChanged(BalanceChangedEvent e) {
        if (e.source.equals(name)) return;     // ignore our own event
        local.evict(e.accountId);              // invalidate stale local copy
        log.info(() -> "[" + name + "] consumed BalanceChanged → evicted local cache for " + e.accountId);
    }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
